/**
 * 浪漫女王卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    /**
     * 显示免费游戏加速效果
     * 加速框的显示
     * @override
     * @constructor
     */
    ShowAntiEffect(bShow,name) {
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find("node_anti",this.node);
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }
                    }
                }
            }
        }else{
            let node = cc.find("node_anti",this.node);
            if(node) {
                node.active = true;
                let spine = node.getComponent(sp.Skeleton);
                spine.setAnimation(0, "TingPai_Intro", false);
                spine.addAnimation(0, "TingPai_Loop", true);
            }else {
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    showBonusAni(boo) {
        let bonusAni = cc.find("node_bonus", this.node);
        bonusAni.active = boo;
    },
});
