    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx - 1;
        let col = idx % this._col
        let row = this._row - Math.floor(idx / this._col) - 1;
        return { col: col, row: row };
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 设置symbol数据
     * @param cards
     * @constructor
     */
    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                res.data = { idx: i + 1 };
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        // 设置掉落数据
        let progressData = SlotsFacade.dm.energyData.progressData;
        if (progressData && progressData.currIdxs) {
            let pd = [] // By JerryWong
            if (Array.isArray(progressData.currIdxs)) { pd = progressData.currIdxs }
            /*progressData.currIdxs*/pd.forEach(idx => {
                let idxInfo = this.transferIdx(idx);
                reelResults[idxInfo.col][idxInfo.row].data.hasStuff = true;
            })
        }

        let spinData = SlotsFacade.dm.getSpinData();
        // 设置bonus数据
        if (spinData.bonusInfo && spinData.bonusInfo.length > 0) {
            spinData.bonusInfo.forEach(item => {
                let idxInfo = this.transferIdx(item.idx);
                if (item.coin) {
                    reelResults[idxInfo.col][idxInfo.row].data.coin = item.coin;
                } else if (item.freeCnt) {
                    reelResults[idxInfo.col][idxInfo.row].data.freeCnt = item.freeCnt;
                }
            })
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

