    /**
     * @override
     * @constructor
     */
    ShowWinTrace: function () {
        let allWinIdx = []

        //中奖位置
        for (let i = 0; i < this._gameInfo.zjLuXian.length; i++) {
            let item = this._gameInfo.zjLuXian[i]
            for (let idx = 0; idx < item.indexs.length; idx++) {
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if (this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs) {
            for (let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++) {
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        // 标记wild 合并情况
        let reels = this._reels;
        let reelsLen = reels.length;
        for (let i = 0; i < reelsLen; i++) {
            let r = reels[i];
            let flags = [false, false, false, false];
            for (let j = 0; j < 4; j++) {
                let s = r._symbols[j];
                let idx = (3 - j) * reelsLen + (i + 1);
                if (s.GetShowId() == 1 && allWinIdx[idx]) {
                    flags[j] = true;
                }
            }
            if (flags[0] && flags[1] && flags[2] && flags[3]) {
                r._symbols[0].wildAniCount = 4;
                r._symbols[1].wildAniCount = 0;
                r._symbols[2].wildAniCount = 0;
                r._symbols[3].wildAniCount = 0;
            } else if (flags[0] && flags[1] && flags[2]) {
                r._symbols[0].wildAniCount = 3;
                r._symbols[1].wildAniCount = 0;
                r._symbols[2].wildAniCount = 0;
            } else if (flags[0] && flags[1]) {
                r._symbols[0].wildAniCount = 2;
                r._symbols[1].wildAniCount = 0;
            } else if (flags[1] && flags[2] && flags[3]) {
                r._symbols[1].wildAniCount = 3;
                r._symbols[2].wildAniCount = 0;
                r._symbols[3].wildAniCount = 0;
            } else if (flags[1] && flags[2]) {
                r._symbols[1].wildAniCount = 2;
                r._symbols[2].wildAniCount = 0;
            } else if (flags[2] && flags[3]) {
                r._symbols[2].wildAniCount = 2;
                r._symbols[3].wildAniCount = 0;
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if (symbol) {
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }


    },

    /**
     * 显示遮罩
     */
    showMask() {
        this.mask.active = true;
        this.mask.opacity = 0;
        cc.tween(this.mask)
            .to(0.2, { opacity: 140 })
            .start();
    },

    /**
     * 隐藏遮罩
     */
    hideMask() {
        if (!this.mask.active) {
            return;
        }
        cc.tween(this.mask)
            .to(0.8, { opacity: 0 })
            .call(res => {
                this.mask.active = false;
            })
            .start();
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 更新所有symbol
     */
    updateAllSymbol() {
        SlotsFacade.dm.updateRandomSymbols();
        for (let reel of this._reels) {
            let symbols = reel._symbols;
            for (let s of symbols) {
                s.StartMove();
                s.ShowRandomSymbol();
            }
        }
    },

    /**
     * 重置所有symbol
     */
    resetAllSymbol() {
        for (let reel of this._reels) {
            for (let s of reel._symbols) {
                s.StartMove();
            }
        }
    }
