/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node,
        bg_dark:cc.Node,
    },

    onLoad() {
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    showBgDark(boo) {
        this.bg_dark.active = boo;
    },

    /**
     * 显示赢取免费次数
     * @param cnt
     * @param isFirstTrigger
     * @param coin
     * @returns {Promise<void>}
     */
    async showWinFreeCnt(cnt, isFirstTrigger, coin) {
        SlotsFacade.soundMgr.playEffect("fgbegin");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        // 免费次数
        let labelCnt = panel.getChildByName("label_cnt");
        labelCnt.getComponent(cc.Label).string = cnt.toString();

        // 每个桃心赢取金币
        let labelCoin = panel.getChildByName("label_coin");
        labelCoin.getComponent(cc.Label).string = Global.convertNumToShort(coin);

        // 是否是第一次触发免费相关提示
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.active = isFirstTrigger;
        panel.getChildByName("first_tip").active = isFirstTrigger;
        panel.getChildByName("extra_tip").active = !isFirstTrigger;

        await SlotsFacade.delayTime(0.5);

        if(isFirstTrigger) {
            await new Promise(res => {
                let handler = () => {
                    SlotsFacade.soundMgr.playEffect("button");
                    okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                    cc.tween(panel)
                        .to(0.5, {scale: 0}, {easing:"backIn"})
                        .call(()=>{
                            this.showBg(false);
                            panel.active = false;
                            res()
                        })
                        .start();
                };
                okBtn.on(cc.Node.EventType.TOUCH_END, handler);
            });
        } else {
            await SlotsFacade.delayTime(1.5);
            SlotsFacade.soundMgr.playEffect("button");
            await new Promise(res=>{
                cc.tween(panel)
                    .to(0.5, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            });
        }
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb
     */
    async showWinCoin(goldNumb) {
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_coin");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        // 文本
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);

        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await SlotsFacade.delayTime(0.5);
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);

                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示jackpot金币
     * @param jpType
     * @param goldNumb
     * @returns {Promise<void>}
     */
    async showWinJpCoin(jpType, goldNumb) {
        SlotsFacade.soundMgr.playEffect("JPwin");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        // jackpot标题
        let title = panel.getChildByName("label_jp_type").getComponent("ImgSwitchCmp");
        title.setIndex(jpType-1);

        // 文本
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);

        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await SlotsFacade.delayTime(0.5);
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);

                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * pick game 开始弹窗
     */
    async showPickGameStart() {
        SlotsFacade.soundMgr.playEffect("bgbegin");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_pick_game_start");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);
        let okBtn = panel.getChildByName("btn_ok");
        await new Promise(res => {
            let handler = () => {
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);
                cc.tween(panel)
                    .to(0.5, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        panel.active = false;
                        this.showBg(false);
                        res()
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * map game 开始弹窗
     */
    async showMapGameStart(page) {
        page = page || 1;
        SlotsFacade.soundMgr.playEffect("mapbegin");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_map_start");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        // 页数
        let labelPage = panel.getChildByName("label").getComponent(cc.Label)
        labelPage.string = page.toString();

        await SlotsFacade.delayTime(0.5);
        let okBtn = panel.getChildByName("btn_ok");
        await new Promise(res => {
            let handler = () => {
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);
                cc.tween(panel)
                    .to(0.5, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        panel.active = false;
                        this.showBg(false);
                        res()
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 赢地图游戏金币
     * @param goldNumb
     * @param page
     * @returns {Promise<void>}
     */
    async showMapGameCoin(goldNumb, page) {
        page = page || 1;
        SlotsFacade.soundMgr.playEffect("mapend");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_map_win_coin");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        // 页数文本
        let labelPage = panel.getChildByName("label_page_cnt").getComponent(cc.Label)
        labelPage.string = page.toString();
        // 金币文本
        let label = panel.getChildByName("label_coin");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);

        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await SlotsFacade.delayTime(0.5);
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);

                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },
})