let RandomSymbols = [];
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        stuff:cc.Node,
        label:cc.Label,
        labelFree:cc.Label,
    },

    onLoad () {
        this.stuff = this.node.getChildByName("stuff");
        this.label = this.node.getChildByName("label").getComponent(cc.Label);
        this.labelFree = this.node.getChildByName("label_free").getComponent(cc.Label);
    },

    //重写
    StartMove: function () {
        this._super();
        this.showStuff(false);
        this.showLabel();
    },

    /**
     * @override
     * @param {*} id
     * @param {*} data
     */
    ShowById:function(id,data){
        this._super(id,data);
        if(data) {
            this.showStuff(true);
            this.showLabel(true);
        }else {
            this.showLabel(false);
        }
    },
    /**
     * 显示收集材料
     */
    showStuff(boo) {
        if(boo && this._data && this._data.hasStuff) {
            this.stuff.active = true;
        }else {
            this.stuff.active = false;
        }
    },

    /**
     * 显示随机符号
     * @override
     */
    ShowRandomSymbol(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1, cfg.randomSymbolsBySkip.length)
        let randVal = cfg.randomSymbolsBySkip[randIdx-1]
        let data = null;
        if(randVal == cfg.bonusId) {
            data = {};
            data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
        }
        this.ShowById(randVal, data);
    },

    /**
     * 显示金币
     * @param boo
     */
    showLabel(boo) {
        this.label.node.active = false;
        this.labelFree.node.active = false;
        if(boo && this._data) {
            if(this._data.coin) {
                this.label.node.active = true;
                this.label.node.scaleX = 1;
                this.label.string = Global.convertNumToShort(this._data.coin);
            }else if(this._data.freeCnt) {
                this.labelFree.node.active = true;
                this.labelFree.node.scaleX = 1;
                this.labelFree.string = Global.convertNumToShort(this._data.freeCnt);
            }
        }
    },

    /**
     * 移动到最低点
     * @override
     * @constructor
     */
    StopMoveDeep() {
        if(!SlotsFacade.dm.getSpinData()) {
            return;
        }
        let idx = this.GetShowId();
        if(idx == SlotsFacade.dm.getGameCfg().scatterId) {
            this.playStopAnimation();
        }
    },

    /**
     * @override
     */
    StopMoveEnd() {
        // 显示要收集的水滴
        this.showStuff(false);
        if(this._data && this._data.hasStuff) {
            SlotsFacade.collect.addAppearanceDrop(this.stuff.convertToWorldSpaceAR(cc.v2(0, 0)));
        }
        // // 播放idle动画
        // let NeedIdleIds = SlotsFacade.dm.getGameCfg().NeedIdleIds;
        // if(NeedIdleIds.includes(this._id)) {
        //     let rewardIdxs = SlotsFacade.dm.getSpinData().rewardIdxs;
        //     if(!rewardIdxs.includes(this._data.idx)) {
        //         this.playidleAnimation();
        //     }
        // }
    },

    /**
     * @override
     */
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    let stopAni = cfg.symbol[id].stop_ani;
                    let idleAni = cfg.symbol[id].idle_ani;
                    nodeSp.setAnimation(0, stopAni.name,false);
                    if(idleAni) {
                        nodeSp.addAnimation(0, idleAni.name, true);
                    }
                }
            }
        }
    },

    /**
     * @override
     * @returns {boolean}
     */
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton);
                if(nodeSp){
                    let triggerAni = cfg.symbol[id].trigger_ani.name;
                    nodeSp.setAnimation(0, triggerAni, cfg.symbol[id].trigger_ani.loop);
                }
            }
            let label = aniNode.getChildByName("label");
            if(!label.active && this._data.coin) {
                label.active = true;
                label.getComponent(cc.Label).string = Global.convertNumToShort(this._data.coin);
            }
        }
        return isPlay;
    },

    /**
     * scatter 图标不显示中奖框
     * @override
     */
    ShowKuang(boo) {
        if(this._id == SlotsFacade.dm.getGameCfg().scatterId) {
            boo = false;
        }
        this._super(boo);
    },

    /**
     * 显示jp图标的文本
     */
    showJpSymbolCoin(coin, delayTime){
        let id = this.GetShowId();
        if(id != 301 && id != 302) {
            return;
        }
        if(!this._showNode) {
            return;
        }
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg();
        this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
        this._showNode.active = true
        let nodeSp = this._showNode.getComponent(sp.Skeleton)
        nodeSp.setAnimation(0, "animation2",false);
        let label = this.node.getChildByName("label").getComponent(cc.Label);
        label.node.active = true;
        label.string = Global.convertNumToShort(coin);
        label.node.scaleX = 0;
        delayTime = delayTime || 1.6;
        cc.tween(label.node)
            .delay(delayTime)
            .to(0.5, {scaleX:1})
            .start();
    },
});
