let PickItemCfg = {
    coin:{aniIn:"XiaoTaoXin_F_Intro", aniShake:"XiaoTaoXin_F_Normal1"},
    jackpot1:{aniIn:"XiaoTaoXin_F_Mini", aniShake:"XiaoTaoXin_V_Normal1"},
    jackpot2:{aniIn:"XiaoTaoXin_F_Minor", aniShake:"XiaoTaoXin_L_Normal1"},
    jackpot3:{aniIn:"XiaoTaoXin_F_Major", aniShake:"XiaoTaoXin_Z_Normal1"},
    jackpot4:{aniIn:"XiaoTaoXin_F_Grand", aniShake:"XiaoTaoXin_H_Normal1"},
}

cc.Class({
    extends: cc.Component,

    properties:{
        panel:cc.Node,
        mask:cc.Node,
        bonus_reel:cc.Node,
        symbols_node:cc.Node,
        symbol_template:cc.Node,

        // 桃心
        taoxin_node:cc.Node,
        spine_taoxin:sp.Skeleton,
        spine_collect_effect:sp.Skeleton,
        label_coin:cc.Label,
        label_pick_cnt:cc.Label,
        collect_coin_particle:cc.Node,

        _symbolArr:null,
        _data:null,
        _respData:null,
        _callBack:null,
    },

    onLoad() {
        this._resetData();

        this._symbolArr = [];
        this.scheduleOnce(()=>{
            for(let i=0; i<16; i++) {
                let item = cc.instantiate(this.symbol_template);
                item.parent = this.symbols_node;
                item.id = i+1;
                item.active = true;
                item.spine = item.getChildByName("spine").getComponent(sp.Skeleton);
                item.label = item.getChildByName("label").getComponent(cc.Label);
                item.tips_add_pick = item.getChildByName("tips_add_pick");
                item.mask = item.getChildByName("mask");
                item.position = this.symbols_node.convertToNodeSpaceAR(SlotsFacade.slots.getIdxGlobalPos(i+1+Math.floor(i/4)));
                item.on(cc.Node.EventType.TOUCH_END, ()=>{
                    this._onPickItem(item);
                })
                this._symbolArr.push(item);
            }
        });
    },

    _resetData() {
        this._data = {
            canPick:false,
            bonusCoin:0, // 当前桃心收集的金币
        };
    },

    /**
     * 点击桃心
     * @param item
     * @private
     */
    _onPickItem(item) {
        if(!this._data.canPick) {
            return;
        }
        let pickBonus = SlotsFacade.dm.pickBonus;
        let itemData = pickBonus.items[item.id-1];
        if(itemData.isOpen) {
            return;
        }
        this._data.canPick = false;
        SlotsFacade.dm.reqSubGame({rtype:3,choiceId:item.id});
    },

    /**
     * 处理服务器返回的消息
     * @private
     */
    async _pickItem() {
        let choiceId = this._respData.choiceId;
        let itemData = this._respData.pickBonus.items[choiceId-1];
        // symbol 相关动画
        let item = this._symbolArr[choiceId-1];
        let aniCfg = null;
        let coinVal = 0;
        if(itemData.coin) {
            coinVal = itemData.coin;
            aniCfg = PickItemCfg.coin;
            item.label.node.active = true;
            item.label.node.opacity = 0;
            item.label.node.scale = 0;
            item.label.string = Global.convertNumToShort(itemData.coin);
            let tw = cc.tween(item.label.node)
                .to(0.2, {scale:1, opacity:0xff}, {easing:"backOut"})
            if(itemData.repick) {
                tw = tw.delay(0.3)
                    .call(()=>{
                        SlotsFacade.soundMgr.playEffect("bgPickTrans");
                    })
                    .to(0.2, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        item.tips_add_pick.active = true;
                        item.tips_add_pick.scale = 0;
                        cc.tween(item.tips_add_pick)
                            .to(0.2, {scale:1}, {easing:"backOut"})
                            .delay(0.5)
                            .to(0.2, {scale:0}, {easing:"backIn"})
                            .start();
                    })
                    .delay(0.9)
                    .to(0.2, {scale:1}, {easing:"backOut"})
            }
            tw.start();
        }else if(itemData.jackpot){
            aniCfg = PickItemCfg[`jackpot${itemData.jackpot.id}`];
            coinVal = itemData.jackpot.value;
        }else {
            console.log("pick game 数据出错")
        }
        item.spine.setAnimation(0, aniCfg.aniIn, false);
        item.spine.addAnimation(0, aniCfg.aniShake, false);

        // 收集
        let particle = cc.instantiate(this.collect_coin_particle);
        particle.active = true;
        particle.parent = this.node;
        particle.position = this.node.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0, 0)));
        let endPos = this.node.convertToNodeSpaceAR(this.taoxin_node.convertToWorldSpaceAR(cc.v2(0,0)))
        cc.tween(particle)
            .to(0.6, {position:endPos})
            .call(()=>{
                particle.removeFromParent(true);
                this.taoxinCollectSymbol({coin:coinVal, pickCnt:itemData.repick?1:0});
            })
            .start()

        await SlotsFacade.delayTime(1);
        if(itemData.jackpot) {
            await SlotsFacade.popup.showWinJpCoin(itemData.jackpot.id, itemData.jackpot.value);
        }
    },

    /**
     * 处理pick 完成逻辑
     * @returns {Promise<void>}
     * @private
     */
    async _settlement() {
        if(this._respData.pickBonus.isEnd) {
            await SlotsFacade.delayTime(1);
            SlotsFacade.soundMgr.playEffect("bgbgmend");
            let pickBonus = this._respData.pickBonus;
            for(let i=0; i<pickBonus.items.length; i++) {
                let vo = pickBonus.items[i];
                let item = this._symbolArr[i];
                if(vo.isOpen) {
                    item.scale = 1.2;
                }else {
                    item.mask.active = true;
                    item.mask.opacity = 0;
                    cc.tween(item.mask).to(0.5, {opacity:0x200}).start();
                    item.zIndex = 100+i*10;
                    let aniCfg = null;
                    if(vo.coin) {
                        aniCfg = PickItemCfg.coin;
                        item.label.string = Global.convertNumToShort(vo.coin);
                        item.label.node.active = true;
                    }else {
                        aniCfg = PickItemCfg[`jackpot${vo.jackpot.id}`];
                    }
                    item.spine.setAnimation(0, aniCfg.aniShake, false);
                }
            }
            await SlotsFacade.delayTime(1.5);
            SlotsFacade.soundMgr.playEffect("bgend");
            await SlotsFacade.popup.showWinCoin(this._respData.pickBonus.winCoin);
            this.exit();
        }else {
            this._data.canPick = true;
        }
    },

    onMsg(msg) {
        this._respData = msg.data;
        SlotsFacade.dm.pickBonus = this._respData.pickBonus;
        this._updateRestCnt();
        this._pickItem();
        this._settlement();
    },

    /**
     * 桃心收集
     * @param boo
     * @param cnt
     */
    async taoxinCollectSymbol(data) {
        SlotsFacade.soundMgr.playEffect("chipCollect");
        this.spine_collect_effect.node.active = true;
        this.spine_collect_effect.setAnimation(0, "DaoTaoXin_Intro", false);
        this.spine_collect_effect.setCompleteListener(()=> {
            this.spine_collect_effect.setCompleteListener(null);
            this.spine_collect_effect.node.active = false;
        });
        this._data.bonusCoin += data.coin || 0;
        this._data.restPickCnt += data.pickCnt || 0;
        if(data.coin) {
            this.label_coin.node.active = true;
            this.label_coin.string = Global.convertNumToShort(this._data.bonusCoin);
        }else if(data.pickCnt) {
            this.label_pick_cnt.node.active = true;
            this.label_pick_cnt.string = this._data.restPickCnt.toString();
            let tip = this.label_pick_cnt.node.getChildByName("tip").getComponent("ImgSwitchCmp");
            tip.setIndex(this._data.restPickCnt>1?0:1);
        }
        await SlotsFacade.delayTime(0.2);
    },

    /**
     * 显示bonus reel
     * @returns {Promise<void>}
     * @private
     */
    async _showBonusReel(isReconnect){
        let scatterIdx = SlotsFacade.dm.getScatterIdx();
        if(!isReconnect) {
            if(scatterIdx) {
                await SlotsFacade.character.collectLove(SlotsFacade.slots.getIdxGlobalPos(scatterIdx));
            }

            SlotsFacade.soundMgr.playEffect("triggering");
            await SlotsFacade.delayTime(2.5);
        }
        this.bonus_reel.active = true;
        SlotsFacade.soundMgr.playEffect("LfExpand");
        let spineLove = this.bonus_reel.getChildByName("spine_love_forever");
        spineLove.active = true;
        if(scatterIdx) {
            spineLove.opacity = 128;
            let endPos = this.bonus_reel.convertToNodeSpaceAR(SlotsFacade.slots.getIdxGlobalPos(scatterIdx));
            spineLove.y = endPos.y;
            cc.tween(spineLove)
                .to(0.5, {opacity:0xff, y:0})
                .start();
            await SlotsFacade.delayTime(0.6);
        }else {
            spineLove.opacity = 0xff;
            spineLove.y = 0;
        }
    },

    _initView() {
        let pickBonus = SlotsFacade.dm.pickBonus;
        this.panel.active = true;
        this.taoxin_node.active = true;
        this.mask.active = true;
        // 初始化symbol
        let items = pickBonus.items;
        for(let i=0; i<this._symbolArr.length; i++) {
            let vo = items[i];
            let item = this._symbolArr[i];
            item.zIndex = i;
            item.scale = 1;
            item.label.node.active = false;
            item.tips_add_pick.active = false;
            item.mask.active = false;
            if(vo.isOpen) {
                let aniCfg = null;
                if(vo.coin) {
                    item.label.node.active = true;
                    item.label.string = Global.convertNumToShort(vo.coin);
                    aniCfg = PickItemCfg.coin;
                }else {
                    aniCfg = PickItemCfg[`jackpot${vo.jackpot.id}`];
                }
                item.spine.setAnimation(0, aniCfg.aniShake, false);
            }else {
                item.spine.setAnimation(0, "XiaoTaoXin_F_Loop2", true);
            }
        }
        // 初始化大桃心
        this.label_coin.node.active = false;
        if(pickBonus.winCoin) {
            this.label_coin.node.active = true;
            this.label_coin.string = Global.convertNumToShort(pickBonus.winCoin);
            this._data.bonusCoin = pickBonus.winCoin;
        }
        this._updateRestCnt();
    },

    /**
     * 更新剩余次数
     * @private
     */
    _updateRestCnt() {
        let restCnt = SlotsFacade.dm.pickBonus.spinCnt;
        this.label_pick_cnt.node.active = true;
        this.label_pick_cnt.string = restCnt.toString();
        let tip = this.label_pick_cnt.node.getChildByName("tip").getComponent("ImgSwitchCmp");
        tip.setIndex(restCnt>1?0:1);
    },

    /**
     * 进入
     * @returns {Promise<void>}
     */
    async enter(callBack, isReconnect) {
        this._callBack = callBack;
        SlotsFacade.slots.resetAllSymbol();
        await this._showBonusReel(isReconnect);
        if(!isReconnect) {
            await SlotsFacade.popup.showPickGameStart();
            await SlotsFacade.mainPanel.showSceneTransition(1);
        }
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.soundMgr.playBgm("bgbgm");
        SlotsFacade.slots.reels_node.active = false;
        this._initView();
        SlotsFacade.character.hide();
        SlotsFacade.collect.hide();
        this._data.canPick = true;
    },

    /**
     * 退出
     */
    async exit() {
        await SlotsFacade.mainPanel.showSceneTransition(1);
        SlotsFacade.mainPanel.showBg(0)
        SlotsFacade.soundMgr.playBgm("", true);
        this._resetData();
        SlotsFacade.character.show();
        SlotsFacade.collect.show();
        this.panel.active = false;
        this.taoxin_node.active = false;
        this.mask.active = false;
        this.bonus_reel.active = false;
        SlotsFacade.slots.reels_node.active = true;
        if(this._callBack) {
            this._callBack(SlotsFacade.dm.pickBonus.winCoin);
            this._callBack = null;
        }
    },
})