/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        energyData  : null,     // 能量数据
        pickBonus   : null,     // pick game 数据
    },

    init(deskInfo,gameId,gameJackpot) {
        this._super(deskInfo,gameId,gameJackpot);
        this.energyData = this._deskInfo.loveCardInfo;
        this.pickBonus = this._deskInfo.pickBonus;
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg(){
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            this.energyData = msg.loveCardInfo;
            this.pickBonus = msg.pickBonus;
        }
        this._super(msg);
    },

    SetSubGameData:function(data){
        this._subGame = data;
    },

    GetSubGameData:function(){
        return this._subGame;
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this._gameInfo.freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
            return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    ///////////////////////////收集相关/////////////////
    /**
     * 获取当前收集进度
     */
    getCollectPercent() {
        if(!this.energyData || !this.energyData.progressData) {
            return 0;
        }
        let percent = this.energyData.progressData.totalCnt / this.energyData.progressData.needCnt;
        percent = Math.min(1, percent);
        percent = Math.max(0, percent);
        return percent;
    },

    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg){
        console.log("<<<< reqSubGame-resp: ", msg);
        if(msg.data.rtype == 1){
            SlotsFacade.map.onMsg(msg);
        } else if(msg.data.rtype == 2){
            SlotsFacade.map.onMsg(msg);
        } else if(msg.data.rtype == 3){
            SlotsFacade.pickGame.onMsg(msg);
        }
    },

    /**
     * 更新随机的 symbols 列表
     */
    updateRandomSymbols() {
        let skipSymbols = [];
        if(SlotsFacade.dm.energyData.freeInfo && SlotsFacade.dm.energyData.freeInfo.removeSymbol) {
            skipSymbols = SlotsFacade.dm.energyData.freeInfo.removeSymbol.concat();
        }
        let cfg = cc.vv.gameData.getGameCfg();
        let rs = cfg.randomSymbols.concat();
        for(let i=0; i<rs.length; i++) {
            if(skipSymbols.includes(rs[i])) {
                rs.splice(i, 1);
                i--;
            }
        }
        this.getGameCfg().randomSymbolsBySkip = rs;
    },

    /**
     * 获取scatter的下标
     */
    getScatterIdx() {
        if(!this._gameInfo || !this._gameInfo.resultCards) {
            return 0;
        }
        let index = this._gameInfo.resultCards.indexOf(this.getGameCfg().scatterId);
        if(index != -1) {
            return index+1;
        }
        return 0;
    }
});
