
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        head:cc.Node,               // 收集条头部节点
        tail:cc.Node,               // 收集条尾部节点
        progressBar: cc.Node,       // 进度条节点
        bar:cc.Node,
        collect_lock:cc.Node,       // 能量条状态节点
        spine_collect_unlock:sp.Skeleton, // 解锁进度条spine动画
        tips:cc.Node,               // 进度条说明提示
        stuff_template:cc.Node,      // 收集图标
        stuff_particle:cc.Node,// 收集粒子

        _isOpen:false,   // 是否打开收集
        _stuffArr:[], // 保存水滴ui资源
    },

    onLoad() {
        this._initListener();
    },

    start() {
        this.scheduleOnce(()=>{
            this._init();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.tail.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            this._showTips();
            if(!this._isOpen) {
                this._openCollect();
            }
        }, this);
    },

    /**
     * 显示收集 说明提示
     */
    _showTips() {
        if(this.tips.active) {
            return;
        }
        this.tips.active = true;
        this.tips.opacity = 0;
        cc.tween(this.tips)
            .to(0.5, { opacity: 0xff })
            .delay(2)
            .to(0.5, {opacity:0})
            .call(()=>{
                this.tips.active = false;
            })
            .start();
    },

    _init() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.showCollect(true);
        this._updateEnterBtnIcon();
    },

    /**
     * 点击按钮进入地图
     * @private
     */
    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        // 自动旋转模式 返回
        if(SlotsFacade.dm.GetAutoModelTime() > 0) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("click");
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.map.enter(()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        }, true);
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        if(!this._stuffArr || this._stuffArr.length<1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("collectFly");
        let endPos = this.head.position;
        this._stuffArr.forEach(drop =>{
            let bezierPos = cc.v2(endPos.x-50, drop.y-300);
            // 移动掉落物品
            cc.tween(drop)
                .then(cc.bezierTo(0.5, [bezierPos, endPos, endPos]))
                // .to(0.5, {x: endPos.x, y: endPos.y, scale:1.2}, {easing:"cubicIn"})
                .call(()=>{
                    drop.removeFromParent();
                })
                .start();
            // 移动粒子
            let stuff = cc.instantiate(this.stuff_particle);
            stuff.active = true;
            stuff.parent = this.node;
            stuff.position = drop.position;
            cc.tween(stuff)
                .then(cc.bezierTo(0.5, [bezierPos, endPos, endPos]))
                // .to(0.5, {x: endPos.x, y: endPos.y, scale:1.2}, {easing:"cubicIn"})
                .call(()=>{
                    stuff.removeFromParent();
                })
                .start();
        });
        this._stuffArr = [];
        await SlotsFacade.delayTime(0.5);
        this._playHeadSpine();
        this.setProgress(SlotsFacade.dm.getCollectPercent());
    },

    /**
     * 头部动画
     */
    _playHeadSpine() {
        SlotsFacade.soundMgr.playEffect("collectIn");
        let headSpine = this.head.getChildByName("spine").getComponent(sp.Skeleton);
        headSpine.setAnimation(0, "ShouJiSuo_Intro", false);
        headSpine.addAnimation(0, "ShouJiSuo_Loop", true);
    },

    /**
     * 显示收集界面
     * @param isInit 是否是初始化
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            this.bar.active = true;
            this.collect_lock.active = false;
            if(!isInit && !this._isOpen) {
                SlotsFacade.soundMgr.playEffect("unlock");
                this.spine_collect_unlock.node.active = true;
                this.spine_collect_unlock.setAnimation(0, "JinDuTiaoJieSuo", false);
            }
        }else {
            this.bar.active = false;
            this.collect_lock.active = true;
            if(!isInit && this._isOpen) {
                this.spine_collect_unlock.node.active = true;
                this.spine_collect_unlock.setAnimation(0, "JinDuTiaoJieSuo", false);
            }
        }
        this._isOpen = boo;
    },

    /**
     * 播放收集完成动画
     */
    async playCollectComplete() {
        SlotsFacade.soundMgr.playEffect("collectComplete");
        let spine = this.tail.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "ShouJiPai_2_Intro", false);
        spine.addAnimation(0, "ShouJiPai_2_Loop", true);
        await new Promise(res=>{
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                res();
            })
        })
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        let w = this.progressBar.width;
        let toX = -w + percent * w;
        if(needTransform) {
            let colectEffect = this.bar.getChildByName("spine_bg").getComponent(sp.Skeleton);
            colectEffect.setAnimation(0, "JDT_Intro", false);
            colectEffect.addAnimation(0, "JDT_Loop", true);
            cc.tween(this.bar).to(0.5, {x:toX}).start();
        }else {
            this.bar.x = toX;
            if(percent == 0) {
                this._updateEnterBtnIcon();
            }
        }
    },

    setEnterEnable(boo) {
        // todo
    },

    /**
     * 更新进入地图按钮图标
     * @private
     */
    _updateEnterBtnIcon() {
        // let energyData = SlotsFacade.dm.energyData;
        // if(!energyData) {
        //     return;
        // }
        // let currId = energyData.currId;
        // if(currId < 1) {
        //     currId = 1;
        // }
        // let mapItemCfg = SlotsFacade.dm.getGameCfg().mapCfg[currId.toString()];
        // let spine = this.tail.getChildByName("spine").getComponent(sp.Skeleton);
        // spine.setAnimation(0, mapItemCfg.iconAni, true);
    },

    /**
     * 添加掉落物品显示
     * @param val
     * @param globalPos
     */
    addAppearanceDrop(globalPos) {
        let drop = cc.instantiate(this.stuff_template);
        drop.active = true;
        drop.parent = this.node;
        drop.position = this.node.convertToNodeSpaceAR(globalPos);
        this._stuffArr.push(drop);
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    }
});
