
cc.Class({
    extends: cc.Component,

    properties: {
        bgMask:cc.Node,
        panel:cc.Node,
        btnClose:cc.Node,
        label_page:cc.Label,
        label_pick:cc.Label,
        label_jackpot:cc.Label,
        label_multiplier:cc.Label,
        label_total_win:cc.Label,
        label_base_price:cc.Label,
        collect_items_node:cc.Node,
        collect_items:[cc.Node],
        pick_result_node:cc.Node,
        pick_results:[cc.Node],
        lottery_cards_node:cc.Node,
        lottery_cards:[cc.Node],

        _callBack:null,
        _respData:null,
        _canTouchCollectItem:false,
    },

    onLoad() {
        // 初始化 collect items
        for(let i=0; i<this.collect_items.length; i++) {
            let item = this.collect_items[i];
            item.id = i+1;
            item.bg = item.getChildByName("bg");
            item.back = item.getChildByName("back");
            item.front = item.getChildByName("front");
            item.icon = item.front.getChildByName("icon").getComponent("ImgSwitchCmp");
            item.mask = item.front.getChildByName("mask");
            item.effect = item.getChildByName("effect").getComponent(sp.Skeleton);
            item.on(cc.Node.EventType.TOUCH_END, ()=>{
                this._onClickCollectItem(item.id);
            }, this)
        }

        // 初始化 lottery card
        for(let i=0; i<this.lottery_cards.length; i++) {
            let item = this.lottery_cards[i];
            item.id = i+1;
            item.back = item.getChildByName("back");
            item.front = item.getChildByName("front").getComponent("ImgSwitchCmp");
            item.little_card_back = item.getChildByName("little_card_back");
            item.spine_effect = item.getChildByName("spine_effect").getComponent(sp.Skeleton);
        }

        // 初始化 pick_results
        for(let i=0; i<this.pick_results.length; i++) {
            let item = this.pick_results[i];
            item.id = i+1;
            item.bg = item.getChildByName("bg").getComponent("ImgSwitchCmp");
            item.label = item.getChildByName("label").getComponent("LabelSwitchCmp");
            item.effect = item.getChildByName("effect").getComponent(sp.Skeleton);
        }

        this.btnClose.on("click", ()=>{
            SlotsFacade.soundMgr.playEffect("button");
            this.btnClose.active = false;
            this.exit();
        }, this);
    },

    /**
     *
     * @param id
     * @private
     */
    _onClickCollectItem(id) {
        if(!this._canTouchCollectItem) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("pairsPick");
        let bonusData = SlotsFacade.dm.energyData.game;
        if(bonusData.items[id-1].isOpen) {
            return;
        }
        SlotsFacade.dm.reqSubGame({rtype:2,choiceId:id});
    },

    /**
     * 处理 点击收集到的卡牌数据
     * @private
     */
    async _pickCollectItem() {
        this._canTouchCollectItem = false;
        let bonusData = this._respData.loveCardInfo.game;
        // 更新剩余次数
        this.label_pick.string = bonusData.restStep;

        let prevIdx = this._respData.result.prevIdx
        let choiceIdx = this._respData.result.choiceIdx
        let preItem = prevIdx && this.collect_items[prevIdx-1];
        let currItem = this.collect_items[choiceIdx-1];
        let mateType = 0;
        if(prevIdx && bonusData.items[prevIdx-1].type == bonusData.items[choiceIdx-1].type) {
            mateType = bonusData.items[choiceIdx-1].type;
        }
        // 翻开卡牌
        SlotsFacade.soundMgr.playEffect("cardTurn");
        cc.tween(currItem)
            .to(0.4, {scaleX:0})
            .call(()=>{
                currItem.back.active = false;
                currItem.front.active = true;
            })
            .to(0.4, {scaleX:1})
            .start();
        await SlotsFacade.delayTime(0.8);
        if(mateType) {
            SlotsFacade.soundMgr.playEffect("pairsRight");
            await SlotsFacade.delayTime(0.4);
            cc.tween(preItem)
                .to(0.2, {scale:1.2})
                .to(0.2, {scale:1})
                .start();
            cc.tween(currItem)
                .to(0.2, {scale:1.2})
                .to(0.2, {scale:1})
                .start();
            await SlotsFacade.delayTime(0.5);
            this._setPickResultItem(mateType, true, true);
            this.label_total_win.string = Global.FormatNumToComma(bonusData.winCoin);
            this.label_multiplier.string = "X" + 5*bonusData.pairItems.length;
        }else {
            if(preItem) {
                SlotsFacade.soundMgr.playEffect("pairsWrong");
                await SlotsFacade.delayTime(0.4);
                SlotsFacade.soundMgr.playEffect("cardClose");
                cc.tween(preItem)
                    .to(0.4, {scaleX:0})
                    .call(()=>{
                        preItem.back.active = true;
                        preItem.front.active = false;
                    })
                    .to(0.4, {scaleX:1})
                    .start();

                cc.tween(currItem)
                    .to(0.4, {scaleX:0})
                    .call(()=>{
                        currItem.back.active = true;
                        currItem.front.active = false;
                    })
                    .to(0.4, {scaleX:1})
                    .start();
                await SlotsFacade.delayTime(0.8);
            }
        }
        if(bonusData.isEnd) {
            // 显示剩余卡牌
            SlotsFacade.soundMgr.playEffect("cardAllturn");
            for(let i=0; i<bonusData.items.length; i++) {
                let vo = bonusData.items[i];
                if(!vo.isOpen) {
                    let item = this.collect_items[i];
                    cc.tween(item)
                        .to(0.4, {scaleX:0})
                        .call(()=>{
                            item.back.active = false;
                            item.front.active = true;
                            item.mask.active = true;
                        })
                        .to(0.4, {scaleX:1})
                        .start();
                }
            }
            await SlotsFacade.delayTime(1.5);
            // 显示赢取金币
            await SlotsFacade.popup.showMapGameCoin(bonusData.winCoin, this._respData.loveCardInfo.page);
            this.exit();
        }else {
            this._canTouchCollectItem = true;
        }
    },

    /**
     * 设置结果卡牌
     * @param type
     * @private
     */
    _setPickResultItem(type, boo, ani) {
        let item = this.pick_results[type-1];
        if(boo) {
            item.bg.setIndex(1);
            item.label.setIndex(1);
            if(ani) {
                SlotsFacade.soundMgr.playEffect("mapMult");
                item.effect.node.active = true;
                item.effect.setAnimation(0, "PuKe_LuoXiaXiao", false);
                item.effect.setCompleteListener(()=>{
                    item.effect.setCompleteListener(null);
                    item.effect.node.active = false;
                });
            }
        }else {
            item.bg.setIndex(0);
            item.label.setIndex(0);
        }
    },

    /**
     * 显示抽奖卡牌
     * @private
     */
    async _showLotteryCards() {
        SlotsFacade.soundMgr.playEffect("cardOpen");
        this.lottery_cards_node.active = true;
        for(let i=0; i<this.lottery_cards.length; i++) {
            // 重置
            let item = this.lottery_cards[i];
            item.active = true;
            item.back.active = true;
            item.front.node.active = false;
            item.little_card_back.active = false;
            item.spine_effect.node.active = false;

            // 移动
            cc.tween(item)
                .to(1, {x:(item.width/2+10)*(i==0?-1:1)})
                .call(()=>{
                    item.spine_effect.node.active = true;
                    item.spine_effect.setAnimation(0, "PuKe_Da_Intro", false);
                    item.spine_effect.addAnimation(0, "PuKe_Da_Loop", true);
                })
                .delay(0.2)
                .call(()=>{
                    item.on(cc.Node.EventType.TOUCH_END, ()=>{
                        SlotsFacade.soundMgr.playEffect("cardPick");
                        this.lottery_cards.forEach(v=>{
                            v.off(cc.Node.EventType.TOUCH_END);
                            if(v != item) {
                                v.spine_effect.node.active = false;
                            }
                            console.log(">>", item.id)
                        });
                        SlotsFacade.dm.reqSubGame({rtype:1, choiceId:item.id});
                    })
                })
                .start();
        }
    },

    /**
     * 抽卡
     * @private
     */
    async _pickLotteryCards() {
        let id = this._respData.choiceId;
        let cnt = this._respData.count;
        await new Promise(res=>{
            let item = this.lottery_cards[id-1];
            item.spine_effect.setAnimation(0, "PuKe_LuoXiaDa", false);
            item.spine_effect.setCompleteListener(()=> {
                item.spine_effect.setCompleteListener(null);
                item.spine_effect.node.active = false;
                res();
            });
        })

        let cntArr = this._respData.counts.concat();
        let index = cntArr.indexOf(cnt);
        if(index != -1) {
            cntArr.splice(index, 1);
        }
        let invalidCnt = cntArr[Math.floor(Math.random()*cntArr.length)];
        // 翻转 移动
        SlotsFacade.soundMgr.playEffect("cardTurn");
        await new Promise(res=>{
            for(let i=0; i<this.lottery_cards.length; i++) {
                // 设置卡牌值
                let item = this.lottery_cards[i];
                if(item.id == id) {
                    item.zIndex = 10;
                    item.front.setIndex(cnt-1);
                    item.front.node.color = new cc.Color().fromHEX("#ffffff");
                }else {
                    item.zIndex = 5;
                    item.front.setIndex(invalidCnt-1);
                    item.front.node.color = new cc.Color().fromHEX("#8B8B8B");
                }

                let tw = cc.tween(item)
                    .to(0.5, {scaleX:0})
                    .call(()=>{
                        item.front.node.active = true;
                        item.back.active = false;
                    })
                    .to(0.5, {scaleX:1})
                    .delay(1)
                    .to(0.5, {x:0});
                if(item.id == id) {
                    tw = tw.to(0.5, {scaleX:0})
                        .call(()=>{
                            item.front.node.active = false;
                            item.little_card_back.active = true;
                        })
                        .to(0.5, {scaleX:1})
                        .call(()=>{
                            res();
                        })
                }
                tw = tw.call(()=>{
                    item.active = false;
                })
                tw.start();
            }
        })
        // 移动到对应卡牌
        await new Promise(res=>{
            for(let i=0; i<cnt; i++) {
                let collectItem = this.collect_items[this._respData.loveCardInfo.currCnt-cnt+i];
                let endPos = this.panel.convertToNodeSpaceAR(collectItem.convertToWorldSpaceAR(cc.v2(0,0)));
                let c = cc.instantiate(this.lottery_cards[0].little_card_back);
                c.active = true;
                c.parent = this.panel;
                c.position = this.lottery_cards_node.position;
                cc.tween(c)
                    .delay(0.2*i)
                    .call(()=>{
                        SlotsFacade.soundMgr.playEffect("cardFly");
                    })
                    .to(0.5, {position:endPos, scale:1})
                    .call(()=>{
                        c.removeFromParent(true);
                        collectItem.back.active = true;
                        collectItem.effect.node.active = true;
                        collectItem.effect.setAnimation(0, "PuKe_Xiao", false);
                        collectItem.effect.setCompleteListener(()=>{
                            collectItem.effect.setCompleteListener(null);
                            collectItem.effect.node.active = false;
                        })
                        if(i==cnt-1) {
                            res();
                        }
                    })
                    .start();
            }
        })
        await SlotsFacade.delayTime(0.5);
        if(SlotsFacade.dm.energyData.state == 2) {
            await this._processCollectFull();
        } else {
            this.exit();
        }
    },

    /**
     * 完成所有收集
     * @returns {Promise<void>}
     * @private
     */
    async _processCollectFull() {
        await SlotsFacade.popup.showMapGameStart(this._respData.loveCardInfo.page);
        this.label_page.node.parent.active = false;
        this.label_pick.node.parent.active = true;
        let bonusData = this._respData.loveCardInfo.game;
        this.label_pick.string = bonusData.restStep;
        for(let i=0; i<this.collect_items.length; i++) {
            let item = this.collect_items[i];
            item.icon.setIndex(bonusData.items[i].type-1);
            item.effect.node.active = true;
            item.effect.setAnimation(0, "PuKe_Xiao", false);
            item.effect.setCompleteListener(()=>{
                item.effect.setCompleteListener(null);
                item.effect.node.active = false;
            })
        }
        await SlotsFacade.delayTime(0.4);
        this._canTouchCollectItem = true;
    },

    /**
     * 抽卡服务器返回
     * @param msg
     */
    onMsg(msg) {
        this._respData = msg.data;
        SlotsFacade.dm.energyData = this._respData.loveCardInfo;
        if(this._respData.rtype == 1) {
            this._pickLotteryCards();
        }else if(this._respData.rtype == 2) {
            this._pickCollectItem();
        }
    },

    /**
     * 初始化界面
     * @private
     */
    _initView() {
        let energyData = SlotsFacade.dm.energyData;
        this.label_base_price.string = Global.FormatNumToComma(energyData.startPrice);
        this.label_jackpot.string = Global.FormatNumToComma(energyData.loveJackpot);
        this.label_multiplier.string = "";
        this.label_total_win.string = "";
        if(energyData.state == 2) {
            let bonusData = energyData.game;
            // 设置金币
            this.label_page.node.parent.active = false;
            this.label_pick.node.parent.active = true;
            this.label_pick.string = bonusData.restStep;
            if(bonusData.winCoin > 0) {
                this.label_total_win.string = Global.FormatNumToComma(bonusData.winCoin);
                this.label_multiplier.string = "X" + 5*bonusData.pairItems.length;
            }
            // 设置pick item
            for(let i=0; i<this.collect_items.length; i++) {
                let vo = bonusData.items[i];
                let item = this.collect_items[i];
                item.back.active = !vo.isOpen;
                item.front.active = vo.isOpen;
                item.icon.setIndex(bonusData.items[i].type-1);
            }
            // 设置pick result
            for(let i=0; i<this.pick_results.length; i++) {
                this._setPickResultItem(i+1, bonusData.pairItems.includes(i+1));
            }
            this._canTouchCollectItem = true;
        } else {
            for(let i=0; i<energyData.currCnt; i++) {
                let item = this.collect_items[i];
                item.back.active = true;
            }
            this.label_page.node.parent.active = true;
            this.label_page.string = energyData.page;
            this.label_pick.node.parent.active = false;
        }
    },

    /**
     * 进入
     * @param callBack
     * @param isView
     * @returns {Promise<void>}
     */
    async enter(callBack, isView) {
        this._callBack = callBack;
        this.bgMask.active = true;
        this.panel.scale = 0;
        this.panel.active = true;
        cc.tween(this.panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);
        this._initView();
        if(isView) {
            this.btnClose.active = true;
        }else {
            SlotsFacade.soundMgr.playBgm("mapbgm");
            SlotsFacade.collect.setProgress(0);
            if(SlotsFacade.dm.energyData.state == 1) {
                this._showLotteryCards();
            }
        }
    },

    _reset() {
        let energyData = SlotsFacade.dm.energyData;
        energyData.state = 0;
        energyData.currCnt = 0;
        energyData.game = null;
        this._respData = null;
        // 设置金币
        this.label_page.node.parent.active = true;
        this.label_page.string = energyData.page>=5?1:energyData.page+1;
        this.label_pick.node.parent.active = false;
        this.label_multiplier.string = "";
        this.label_total_win.string = "";
        // 设置pick item
        for(let i=0; i<this.collect_items.length; i++) {
            let item = this.collect_items[i];
            item.back.active = false;
            item.front.active = false;
            item.mask.active = false;
        }
        // 设置pick result
        for(let i=0; i<this.pick_results.length; i++) {
            this._setPickResultItem(i+1, false);
        }
    },

    /**
     * 退出
     * @returns {Promise<void>}
     */
    async exit() {
        SlotsFacade.soundMgr.playEffect("mapOpenClose");
        await new Promise(res=>{
            cc.tween(this.panel)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.panel.active = false;
                    this.bgMask.active = false;
                    res();
                })
                .start();
        })
        if(SlotsFacade.dm.energyData.state == 2) {
            this._reset();
        }
        SlotsFacade.soundMgr.playBgm("", true);
        if(this._callBack) {
            this._callBack();
        }
    }
});
