cc.Class({
    extends: cc.Component,

    properties: {
        spine_role:sp.Skeleton,
        // spine_collect_effect:sp.Skeleton,
        // love_title:cc.Node,
        // love_particle:cc.Node,
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    },

    onLoad() {
    },

    start() {
    },

    async collectLove(globalPos) {
        return;
        let p = cc.instantiate(this.love_particle);
        p.active = true;
        p.parent = SlotsFacade.mainPanel.top_node;
        p.position = p.parent.convertToNodeSpaceAR(globalPos);
        let endPos = p.parent.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0,0)));
        cc.tween(p)
            .to(0.6, {position:endPos})
            .call(()=>{
                p.removeFromParent(true);
                SlotsFacade.soundMgr.playEffect("chipCollect");
                this.spine_collect_effect.node.active = true;
                this.spine_collect_effect.setAnimation(0, "DaoTaoXin_Intro", false);
                this.spine_collect_effect.setCompleteListener(()=> {
                    this.spine_collect_effect.setCompleteListener(null);
                    this.spine_collect_effect.node.active = false;
                });
            })
            .start();
        await SlotsFacade.delayTime(0.6);
    }
});
