let PickItemCfg = {
    coin: { aniIn: "XiaoTaoXin_F_Intro", aniShake: "XiaoTaoXin_F_Normal1", },
    jackpot4: { aniIn: "XiaoTaoXin_F_Grand", aniShake: "XiaoTaoXin_H_Normal1" },
}

cc.Class({
    extends: cc.Component,

    properties: {
        panel: cc.Node,
        mask: cc.Node,
        spine_border: sp.Skeleton,
        symbols_node: cc.Node,
        // bonus reel
        bonus_reel: cc.Node,
        spine_reel_bg: sp.Skeleton,
        spine_love_forever: sp.Skeleton,
        label_free_coin: cc.Label,
        // 桃心
        taoxin_node: cc.Node,
        spine_taoxin: sp.Skeleton,
        spine_collect_effect: sp.Skeleton,
        label_coin: cc.Label,
        label_free_cnt: cc.Label,
        collect_coin_particle: cc.Node,
        collect_love_particle: cc.Node,
        symbol_template: cc.Node,
        _symbolArr: null,
        _data: null,
    },

    onLoad() {
        this._resetData();
    },

    _resetData() {
        this._data = {
            isEnter: false,
            bonusCoin: 0, // 当前桃心收集的金币
            freeBaseCoin: 0, // 当前免费单个桃心的金币
            restFreeCnt: 0,  // 免费剩余次数
        };
    },

    start() { },

    enter() { },

    /**
     * 退出
     */
    exit() {
        SlotsFacade.soundMgr.playEffect("reelLightOff");
        this._resetData();
        SlotsFacade.character.show();
        SlotsFacade.collect.show();
        this.panel.active = false;
        this.mask.active = false;
        this.spine_border.node.active = false;
        this.taoxin_node.active = false;
        this.label_coin.node.active = false;
        this.label_coin.string = "";
        this.label_free_cnt.node.active = false;
        this.label_free_cnt.string = "";
        // bonus reel
        this.spine_reel_bg.node.active = false;
        this.spine_love_forever.node.active = false;
        this.spine_love_forever.node.getChildByName("tip").active = false;
        this.label_free_coin.node.active = false;
    },

    /**
     * 点击开始移动
     */
    startMove() {
        if (!this._data.isEnter) {
            return;
        }
        this.mask.active = true;
        this._updateFreeCnt();
    },

    /**
     * 更新免费次数
     * @private
     */
    _updateFreeCnt() {
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true, total - rest, total);
        this._data.restFreeCnt = rest;
        this.label_free_cnt.string = rest.toString();
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        if (this._data.isEnter) {
            return;
        }
        if (SlotsFacade.dm.GetTotalFree()) {
            this._data.isEnter = true;
            return;
        }
        if (SlotsFacade.dm.getSpinData().bonusTotalCoin) {
            this._data.isEnter = true;
            return;
        }
        if (SlotsFacade.dm.getSpinData().bonusGame) {
            this._data.isEnter = true;
            return;
        }
    },

    /**
     * 生成一个wild图标
     */
    genASymbol(data) {
        let node = cc.instantiate(this.symbol_template)
        node.active = true;
        node.spine = node.getChildByName("spine").getComponent(sp.Skeleton);
        node.label = node.getChildByName("label").getComponent(cc.Label);
        node.label_free = node.getChildByName("label_free").getComponent(cc.Label);
        node.parent = this.symbols_node;
        if (data.coin) {
            node.label.node.active = true;
            node.label.string = Global.convertNumToShort(data.coin);
            node.spine.setAnimation(0, "XiaoTaoXin_F_Loop2", true);
        } else if (data.freeCnt) {
            node.label_free.node.active = true;
            node.label_free.string = data.freeCnt;
            node.spine.setAnimation(0, "XiaoTaoXin_J_Loop2", true);
        }
        let pos = SlotsFacade.slots.getIdxGlobalPos(data.idx);
        pos = this.symbols_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return node;
    },

    /**
     * 生成bonus图标
     */
    genBonusSymbols() {
        let spinData = SlotsFacade.dm.getSpinData();
        let bonusInfo = spinData.bonusInfo;
        if (!bonusInfo || bonusInfo.length < 1) {
            return;
        }
        this._symbolArr = [];
        bonusInfo = (Array.isArray(bonusInfo)) ? bonusInfo : (bonusInfo && typeof bonusInfo === "object") ? Object.values(bonusInfo) : [] // By JerryWong
        bonusInfo.sort((a, b) => {
            let colA = (a.idx - 1) % 5;
            let colB = (b.idx - 1) % 5;
            if (colA - colB == 0) {
                return a.idx - b.idx;
            } else {
                return colA - colB;
            }
        });
        for (let i = 0; i < bonusInfo.length; i++) {
            let symbol = this.genASymbol(bonusInfo[i]);
            this._symbolArr.push(symbol);
        }
    },

    /**
     * 收集桃心金币
     * @private
     */
    async _processBonusCoin() {
        let spinData = SlotsFacade.dm.getSpinData();
        let bonusInfo = spinData.bonusInfo;
        if (bonusInfo && bonusInfo.length < 1) {
            return;
        }
        this._enterBonusState();
        this.genBonusSymbols();
        await SlotsFacade.delayTime(0.3);
        this.spine_taoxin.setAnimation(0, "DaoTaoXin_N_Loop2", true);
        let endPos = this.node.convertToNodeSpaceAR(this.taoxin_node.convertToWorldSpaceAR(cc.v2(0, 0)));
        for (let i = 0; i < this._symbolArr.length; i++) {
            let symbol = this._symbolArr[i];
            let aniName = "";
            if (symbol.label.node.active) {
                aniName = "XiaoTaoXin_F_Intro";
            } else if (symbol.label_free.node.active) {
                aniName = "XiaoTaoXin_J_Intro";
            }
            symbol.spine.setAnimation(0, aniName, false);
            SlotsFacade.soundMgr.playEffect("fgChipCollect");
            let startPos = this.node.convertToNodeSpaceAR(symbol.convertToWorldSpaceAR(cc.v2(0, 0)));
            let particle = cc.instantiate(this.collect_coin_particle);
            particle.active = true;
            particle.parent = this.node;
            particle.position = startPos;
            await new Promise(res => {
                cc.tween(particle)
                    .to(0.5, { position: endPos })
                    .call(async () => {
                        particle.removeFromParent(true);
                        await this.taoxinCollectSymbol(bonusInfo[i]);
                        res();
                    })
                    .start();
            })
        }
        await SlotsFacade.delayTime(1);
        this.spine_taoxin.setAnimation(0, "DaoTaoXin_N_Loop", true);
    },

    /**
     * 归集bonus 金币 到免费金币
     * @private
     */
    async _processFreeCoin() {
        if (!SlotsFacade.dm.isTriggerFree()) {
            return;
        }
        if (SlotsFacade.dm.isFistTriggerFree()) {
            await this._showBonusReel();
        }
        if (this.spine_love_forever.animation != "LoveForever_Loop3") {
            this.spine_love_forever.setAnimation(0, "LoveForever_Intro3", false);
            this.spine_love_forever.addAnimation(0, "LoveForever_Loop3", false);
            this.spine_love_forever.setCompleteListener(() => {
                this.spine_love_forever.setCompleteListener(null);
                this.spine_love_forever.node.getChildByName("tip").active = true;
            });
        }
        let spinData = SlotsFacade.dm.getSpinData();
        let bonusInfo = spinData.bonusInfo;
        let endPos = this.node.convertToNodeSpaceAR(this.bonus_reel.convertToWorldSpaceAR(cc.v2(0, 0)));
        for (let i = 0; i < this._symbolArr.length; i++) {
            let vo = bonusInfo[i];
            let symbol = this._symbolArr[i];
            if (!vo.coin) {
                continue;
            }
            SlotsFacade.soundMgr.playEffect("fgChipCollect");
            let startPos = this.node.convertToNodeSpaceAR(symbol.convertToWorldSpaceAR(cc.v2(0, 0)));
            let cloneSymbol = cc.instantiate(symbol);
            cloneSymbol.parent = this.node;
            cloneSymbol.position = startPos;
            this._data.freeBaseCoin += vo.coin;
            await new Promise(res => {
                cc.tween(cloneSymbol)
                    .to(0.2, { scale: 1.3 })
                    .to(0.5, { position: endPos, scale: 1 })
                    .call(async () => {
                        cloneSymbol.removeFromParent(true);
                        this.label_free_coin.node.active = true;
                        this.label_free_coin.string = Global.convertNumToShort(this._data.freeBaseCoin);
                        res();
                    })
                    .start();
            })
        }
        this._updateFreeCnt();
    },

    /**
     * 桃心收集
     * @param boo
     * @param cnt
     */
    async taoxinCollectSymbol(data) {
        this.spine_collect_effect.node.active = true;
        this.spine_collect_effect.setAnimation(0, "DaoTaoXin_Intro", false);
        this.spine_collect_effect.setCompleteListener(() => {
            this.spine_collect_effect.setCompleteListener(null);
            this.spine_collect_effect.node.active = false;
        });
        this._data.bonusCoin += data.coin || 0;
        this._data.restFreeCnt += data.freeCnt || 0;
        if (data.coin) {
            this.label_coin.node.active = true;
            this.label_coin.string = Global.convertNumToShort(this._data.bonusCoin);
        } else if (data.freeCnt) {
            this.label_free_cnt.node.active = true;
            this.label_free_cnt.string = this._data.restFreeCnt.toString();
            let tip = this.label_free_cnt.node.getChildByName("tip").getComponent("ImgSwitchCmp");
            tip.setIndex(this._data.restFreeCnt > 1 ? 0 : 1);
        }
        await SlotsFacade.delayTime(0.2);
    },

    /**
     * 进入bonus 状态
     */
    _enterBonusState() {
        SlotsFacade.soundMgr.playEffect("reelLightOn");
        this.panel.active = true;
        SlotsFacade.character.hide();
        SlotsFacade.collect.hide();
        this.spine_border.node.active = true;
        this.taoxin_node.active = true;
        this.mask.active = true;
    },

    /**
     * 显示bonus reel
     * @returns {Promise<void>}
     * @private
     */
    async _showBonusReel(isReconnect) {
        isReconnect = isReconnect || false;
        if (!SlotsFacade.dm.isFistTriggerFree() && !isReconnect) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("LfExpand");
        this.spine_reel_bg.node.active = true;
        this.spine_love_forever.node.active = true;
        this.spine_love_forever.setAnimation(0, "LoveForever_Loop2", true);
        let scatterIdx = SlotsFacade.dm.getScatterIdx();
        if (scatterIdx) {
            this.spine_love_forever.node.opacity = 128;
            let endPos = this.bonus_reel.convertToNodeSpaceAR(SlotsFacade.slots.getIdxGlobalPos(scatterIdx));
            this.spine_love_forever.node.y = endPos.y;
            cc.tween(this.spine_love_forever.node)
                .to(0.5, { opacity: 0xff, y: 0 })
                .start();
            await SlotsFacade.delayTime(0.6);
        } else {
            this.spine_love_forever.node.opacity = 0xff;
            this.spine_love_forever.node.y = 0;
        }
    },

    /**
     * 显示love symbol
     * @private
     */
    _showLoveSymbol() {
        let scatterIdx = SlotsFacade.dm.getScatterIdx();
        if (!scatterIdx) {
            return;
        }

        // 首次触发freegame 或者 非免费游戏中bonus 显示 love symbol
        if (SlotsFacade.dm.isFistTriggerFree() ||
            (SlotsFacade.dm.GetTotalFree() < 1 && SlotsFacade.dm.getSpinData().bonusInfo && SlotsFacade.dm.getSpinData().bonusInfo.length > 0)
        ) {
            this.spine_love_forever.node.active = true;
            this.spine_love_forever.node.y = this.bonus_reel.convertToNodeSpaceAR(SlotsFacade.slots.getIdxGlobalPos(scatterIdx)).y;
            this.spine_love_forever.setAnimation(0, "LoveForever_Loop2", true);
        }
    },

    async _collectLoveToCharacter() {
        let scatterIdx = SlotsFacade.dm.getScatterIdx();
        if (!scatterIdx) {
            return;
        }
        if (SlotsFacade.dm.isFistTriggerFree() ||
            (SlotsFacade.dm.GetTotalFree() < 1 && SlotsFacade.dm.getSpinData().bonusInfo && SlotsFacade.dm.getSpinData().bonusInfo.length > 0)
        ) {
            await SlotsFacade.character.collectLove(SlotsFacade.slots.getIdxGlobalPos(scatterIdx));
            SlotsFacade.soundMgr.playEffect("triggering");
            await SlotsFacade.delayTime(2.5);
        }
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        if (!this._data.isEnter) {
            return;
        }
        await this._collectLoveToCharacter();
        this._showLoveSymbol();
        await this._processBonusCoin();
        await this._processFreeCoin();
        this._clearBonusSymbol();
        this.mask.active = false;
        if (SlotsFacade.dm.GetTotalFree() < 1) {
            this.exit();
        }
    },

    /**
     * 隐藏wild
     * @private
     */
    _clearBonusSymbol() {
        this._symbolArr = [];
        this.symbols_node.removeAllChildren(true);
    },

    reconnect() {
        this._enterBonusState();
        let deskData = SlotsFacade.dm.getDeskInfo();
        // 显示桃心信息
        this.label_coin.node.active = true;
        this.label_coin.string = Global.convertNumToShort(deskData.bonusTotalCoin);
        this.label_free_cnt.node.active = true;
        this.label_free_cnt.string = SlotsFacade.dm.GetFreeTime();
        // 显示bonus reel
        this._showBonusReel(true);
    }
})